import { getDb } from "@/lib/db";
import { mailMessage, signupRequest } from "@/lib/schema";

export const reviewRequestFields = {
  id: signupRequest.id,
  givenName: signupRequest.givenName,
  familyName: signupRequest.familyName,
  contactEmail: signupRequest.contactEmail,
  contactEmailConfirmedByAdmin: signupRequest.contactEmailConfirmedByAdmin,
  phone: signupRequest.phone,
  connection: signupRequest.connection,
  status: signupRequest.status,
  rejectionReason: signupRequest.rejectionReason,
  createdAt: signupRequest.createdAt,
};

const reviewableStatuses = ["verified", "rejection_pending_notification"] as const;

export async function listReviewableSignupRequests(database = getDb) {
  return database()
    .select(reviewRequestFields)
    .from(signupRequest)
    .where(
      or(
        eq(signupRequest.status, reviewableStatuses[0]),
        eq(signupRequest.status, reviewableStatuses[1]),
      ),
    )
    .orderBy(signupRequest.createdAt);
}

export async function getReviewableSignupRequest(id: string, database = getDb) {
  const [request] = await database()
    .select(reviewRequestFields)
    .from(signupRequest)
    .where(
      and(
        eq(signupRequest.id, id),
        or(
          eq(signupRequest.status, reviewableStatuses[0]),
          eq(signupRequest.status, reviewableStatuses[1]),
        ),
      ),
    )
    .limit(1);
  return request;
}

export type SignupRequestCorrection = Pick<
  typeof signupRequest.$inferInsert,
  | "givenName"
  | "familyName"
  | "contactEmail"
  | "contactEmailConfirmedByAdmin"
  | "phone"
  | "connection"
>;

export async function correctVerifiedSignupRequest(
  id: string,
  correction: SignupRequestCorrection,
  database = getDb,
) {
  const [request] = await database()
    .update(signupRequest)
    .set(correction)
    .where(and(eq(signupRequest.id, id), eq(signupRequest.status, "verified")))
    .returning(reviewRequestFields);
  return request;
}

export async function beginSignupRejection(id: string, reason: string, database = getDb) {
  const [request] = await database()
    .update(signupRequest)
    .set({
      status: "rejection_pending_notification",
      rejectionReason: reason,
      rejectedAt: new Date(),
    })
    .where(and(eq(signupRequest.id, id), eq(signupRequest.status, "verified")))
    .returning(reviewRequestFields);
  return request;
}

export function rejectionMessage(reason: string) {
  return `Your Workspace signup request was not approved. Reason: ${reason}`;
}

export async function captureRejectionNotification(id: string, database = getDb) {
  return database().transaction(async (tx) => {
    const [request] = await tx
      .update(signupRequest)
      .set({ status: "rejection_pending_notification" })
      .where(
        and(eq(signupRequest.id, id), eq(signupRequest.status, "rejection_pending_notification")),
      )
      .returning({
        id: signupRequest.id,
        contactEmail: signupRequest.contactEmail,
        rejectionReason: signupRequest.rejectionReason,
      });
    if (!request?.rejectionReason) return undefined;

    await tx.insert(mailMessage).values({
      signupRequestId: request.id,
      to: request.contactEmail,
      subject: "Your Workspace signup request",
      text: rejectionMessage(request.rejectionReason),
    });
    const [completed] = await tx
      .update(signupRequest)
      .set({ status: "rejected" })
      .where(
        and(eq(signupRequest.id, id), eq(signupRequest.status, "rejection_pending_notification")),
      )
      .returning(reviewRequestFields);
    return completed;
  });
}
import { z } from "zod";

const optionalText = (maxLength: number, message: string) =>
  z
    .string()
    .trim()
    .max(maxLength, message)
    .optional()
    .transform((value) => value || null);

const correctionSchema = z.object({
  givenName: z.string().trim().min(1, "Enter the given name.").max(100, "Enter the given name."),
  familyName: z.string().trim().min(1, "Enter the family name.").max(100, "Enter the family name."),
  contactEmail: z
    .string()
    .trim()
    .toLowerCase()
    .max(254, "Enter a valid contact email.")
    .email("Enter a valid contact email."),
  contactEmailConfirmedByAdmin: z.boolean(),
  phone: optionalText(50, "Enter a phone number of 50 characters or fewer."),
  connection: optionalText(1000, "Keep the connection explanation to 1,000 characters or fewer."),
});

const rejectionSchema = z.object({
  reason: z
    .string()
    .trim()
    .min(1, "Enter a reason for the applicant.")
    .max(1000, "Keep the rejection reason to 1,000 characters or fewer."),
});

type Errors = Partial<Record<keyof z.output<typeof correctionSchema> | "reason", string>>;

function parse<T extends z.ZodType>(
  schema: T,
  value: unknown,
): { data: z.output<T>; errors: undefined } | { data: undefined; errors: Errors } {
  const result = schema.safeParse(value);
  if (result.success) return { data: result.data, errors: undefined };
  const errors: Errors = {};
  for (const issue of result.error.issues) {
    const field = issue.path[0];
    if (typeof field === "string" && !errors[field as keyof Errors])
      errors[field as keyof Errors] = issue.message;
  }
  return { data: undefined, errors };
}

export function parseReviewCorrectionInput(value: unknown) {
  return parse(correctionSchema, value);
}

export function parseRejectionInput(value: unknown) {
  return parse(rejectionSchema, value);
}
import "server-only";

import { eq } from "drizzle-orm";
import { z } from "zod";

import { db } from "@/lib/db";
import { workspaceIdentity } from "@/lib/schema";

const identitySchema = z.object({
  sub: z.string().min(1).max(255),
  hd: z.string().min(1),
  email: z.email(),
  email_verified: z.literal(true),
});

const profileSchema = z.object({
  id: z.string().min(1),
  primaryEmail: z.email(),
  name: z.object({ fullName: z.string() }).optional(),
  thumbnailPhotoUrl: z.url().optional(),
});

const roleAssignmentsSchema = z.object({
  items: z.array(z.object({ roleId: z.string() })).optional(),
  nextPageToken: z.string().optional(),
});

export class WorkspaceUnavailable extends Error {
  constructor(public readonly reconnect = false) {
    super(reconnect ? "Reconnect your Google account" : "Workspace unavailable");
  }
}

export function validateIdentity(input: unknown) {
  const identity = identitySchema.parse(input);
  if (!process.env.GOOGLE_WORKSPACE_DOMAIN || identity.hd !== process.env.GOOGLE_WORKSPACE_DOMAIN)
    throw new WorkspaceUnavailable(true);
  return identity;
}

async function googleGet(url: string, accessToken: string) {
  const response = await fetch(url, {
    headers: { Authorization: `Bearer ${accessToken}` },
    cache: "no-store",
    signal: AbortSignal.timeout(10_000),
  });
  if (!response.ok) {
    await logGoogleFailure(url, response);
    throw new WorkspaceUnavailable(response.status === 401);
  }
  return response.json();
}

async function logGoogleFailure(url: string | URL, response: Response) {
  const parsed = z
    .object({
      error: z.object({
        errors: z
          .array(
            z.object({
              reason: z
                .string()
                .regex(/^[\w.]+$/)
                .max(100),
            }),
          )
          .optional(),
      }),
    })
    .safeParse(await response.json().catch(() => null));
  console.error("[workspace] Google API rejected request", {
    endpoint: new URL(url).pathname.replace(/\/users\/[^/]+/, "/users/{userKey}"),
    status: response.status,
    reasons: parsed.success ? parsed.data.error.errors?.map(({ reason }) => reason) : undefined,
  });
}

export async function readWorkspaceProfile(
  accessToken: string,
  subject: string,
  allowInitialBinding = false,
) {
  const identity = validateIdentity(
    await googleGet("https://openidconnect.googleapis.com/v1/userinfo", accessToken),
  );
  if (identity.sub !== subject) throw new WorkspaceUnavailable(true);

  const [binding] = await db
    .select()
    .from(workspaceIdentity)
    .where(eq(workspaceIdentity.googleSubject, subject));
  if (!binding && !allowInitialBinding) throw new WorkspaceUnavailable(true);

  const url = new URL(
    `https://admin.googleapis.com/admin/directory/v1/users/${encodeURIComponent(binding?.directoryId ?? identity.email)}`,
  );
  url.searchParams.set("viewType", "domain_public");
  url.searchParams.set("fields", "id,primaryEmail,name(fullName),thumbnailPhotoUrl");
  const profile = profileSchema.parse(await googleGet(url.toString(), accessToken));
  if (
    profile.primaryEmail.toLowerCase() !== identity.email.toLowerCase() ||
    (binding && profile.id !== binding.directoryId)
  )
    throw new WorkspaceUnavailable(true);

  if (!binding) {
    await db
      .insert(workspaceIdentity)
      .values({ googleSubject: subject, directoryId: profile.id })
      .onConflictDoNothing();
    const [saved] = await db
      .select()
      .from(workspaceIdentity)
      .where(eq(workspaceIdentity.googleSubject, subject));
    if (saved?.directoryId !== profile.id) throw new WorkspaceUnavailable(true);
  }
  return profile;
}

export async function hasReviewerRole(accessToken: string, directoryId: string, roleId: string) {
  const url = new URL(
    "https://admin.googleapis.com/admin/directory/v1/customer/my_customer/roleassignments",
  );
  url.searchParams.set("userKey", directoryId);
  url.searchParams.set("includeIndirectRoleAssignments", "true");
  let pageToken: string | undefined;
  do {
    const response = await fetch(url, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) {
      await logGoogleFailure(url, response);
      if (response.status === 403) return false;
      throw new WorkspaceUnavailable(response.status === 401);
    }
    const assignments = roleAssignmentsSchema.parse(await response.json());
    if (assignments.items?.some((item) => item.roleId === roleId)) return true;
    pageToken = assignments.nextPageToken;
    if (pageToken) url.searchParams.set("pageToken", pageToken);
  } while (pageToken);
  return false;
}

